#include <stdio.h>
#include <math.h>

int main(void)
{
    double a, b, c, delta, x1, x2;

    printf("Input a, b, c: ");
    scanf("%lf%lf%lf", &a, &b, &c);

    delta = b * b - 4 * a * c;
    // 计算两个实根
    x1 = (-b + sqrt(delta)) / (2 * a);
    x2 = (-b - sqrt(delta)) / (2 * a);

    printf("x1 = %f\n", x1);
    printf("x2 = %f\n", x2);

    return 0;
}

#include <stdio.h>

// 方法1：使用宏定义
#define PI_MACRO 3.14159

int main(void)
{
    // 方法2：使用const常量
    const double PI_CONST = 3.14159;

    double r, v, s;

    printf("Input r: ");
    scanf("%lf", &r);

    // 使用宏常量计算
    v = 4.0 / 3.0 * PI_MACRO * r * r * r;
    s = 4.0 * PI_MACRO * r * r;
    printf("Using Macro: Volume = %f, Surface Area = %f\n", v, s);

    // 使用const常量计算
    v = 4.0 / 3.0 * PI_CONST * r * r * r;
    s = 4.0 * PI_CONST * r * r;
    printf("Using Const: Volume = %f, Surface Area = %f\n", v, s);

    return 0;
}

