#include <stdio.h>

int main(void) {
    float principal, rate, total;
    int year;

    printf("Input principal and year: ");
    scanf("%f %d", &principal, &year);

    switch (year) {
        case 1: rate = 0.0225; break;
        case 2: rate = 0.0243; break;
        case 3: rate = 0.0270; break;
        case 5: rate = 0.0288; break;
        case 8: rate = 0.0300; break;
        default:
            printf("Invalid year!\n");
            return 1;
    }

    total = principal * (1 + rate * year);
    printf("Total amount: %.2f\n", total);

    return 0;
}

