void Hanoi(int n, char src, char aux, char dest)
{
    if (n == 1)
    {
        Move(1, src, dest);
    }
    else
    {
        Hanoi(n - 1, src, dest, aux); // 将n-1个盘子从src移到aux
        Move(n, src, dest);           // 将第n个盘子从src移到dest
        Hanoi(n - 1, aux, src, dest); // 将n-1个盘子从aux移到dest
    }
}

