int SumDiagonal(int a[][MAX_N], int n)
{
    int i, sum = 0;
    for(i = 0; i < n; i++)
    {
        // 主对角线: a[i][i]
        sum += a[i][i];

        // 副对角线: a[i][n-1-i]
        // 如果是奇数阶矩阵，中心元素在上面加了一次，这里需要避免重复加
        if(i != n - 1 - i)
        {
            sum += a[i][n - 1 - i];
        }
    }
    return sum;
}
