    printf("\nArray B: ");
    for(i=0; i<5; i++) printf("%d ", b[i]);

    SwapArray(a, b, 5);

    printf("\n\nAfter swap:\n");
    printf("Array A: ");
    for(i=0; i<5; i++) printf("%d ", a[i]);
