#include <stdio.h>

void Swap(int *x, int *y) {
    int temp = *x;
    *x = *y;
    *y = temp;
}

void ProcessArray(int *arr, int n) {
    int *max = arr; // 指向最大值的指针
    int *min = arr; // 指向最小值的指针
    int i;

    // 寻找最大值和最小值的地址
    for (i = 1; i < n; i++) {
        if (arr[i] > *max) max = &arr[i];
        if (arr[i] < *min) min = &arr[i];
    }

    // 交换最大值与第一个元素
    Swap(arr, max);

    // 注意：如果最小值恰好在第一个位置，且刚才被交换到了max的位置
    // 需要重新判断min的位置，或者在交换前处理
    // 但本题简单处理，若min指向原第一个位置，交换后min内容变了，指向没变
    // 此时原第一个位置已经是最大值了，这可能不符合“最小值与最后一个元素交换”的原意（如果原意是值交换）
    // 更严谨的做法是记录索引。这里按题目常规理解，再次寻找最小值位置进行交换可能更稳妥，
    // 或者如果min指针指向的位置就是第一个元素，交换后min应该指向新的位置。

    // 为防止交换干扰，重新寻找最小值位置（最稳妥做法）
    min = arr; 
    for (i = 1; i < n; i++) {
        if (arr[i] < *min) min = &arr[i];
    }

    // 交换最小值与最后一个元素
    Swap(arr + n - 1, min);
}

int main() {
    int a[10], i;
    printf("Input 10 integers: ");
    for (i = 0; i < 10; i++) scanf("%d", &a[i]);

    ProcessArray(a, 10);

    printf("Result: ");
    for (i = 0; i < 10; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

// 判断闰年
int IsLeap(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// 计算某月的天数
int MaxDay(int year, int month) {
    int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (IsLeap(year)) days[2] = 29;
    return days[month];
}

// (1) 年月日 -> 第几天
int DayofYear(int year, int month, int day) {
    int i, total = 0;
    for (i = 1; i < month; i++) {
        total += MaxDay(year, i);
    }
    total += day;
    return total;
}

// (2) 第几天 -> 月日
void MonthDay(int year, int yearDay, int *pMonth, int *pDay) {
    int i = 1;
    int daysInMonth;
    while (1) {
        daysInMonth = MaxDay(year, i);
        if (yearDay <= daysInMonth) break;
        yearDay -= daysInMonth;
        i++;
    }
    *pMonth = i;
    *pDay = yearDay;
}

int main() {
