#include <stdio.h>

// 数组版本
void DelCharArr(char str[], char c) {
    int i, j;
    for (i = 0, j = 0; str[i] != '\0'; i++) {
        if (str[i] != c) {
            str[j++] = str[i];
        }
    }
    str[j] = '\0';
}

// 指针版本
void DelCharPtr(char *str, char c) {
    char *p = str;
    while (*str != '\0') {
        if (*str != c) {
            *p++ = *str;
        }
        str++;
    }
    *p = '\0';
}

int main() {
    char s1[] = "Hello World";
    char s2[] = "Hello World";
    DelCharArr(s1, 'o');
    DelCharPtr(s2, 'l');
    printf("Array del 'o': %s\n", s1);
    printf("Pointer del 'l': %s\n", s2);
    return 0;
}

#include <stdio.h>
#include <string.h>

// 数组版本
void ReverseArr(char str[]) {
    int i, j;
    char temp;
    j = strlen(str) - 1;
    for (i = 0; i < j; i++, j--) {
        temp = str[i];
        str[i] = str[j];
        str[j] = temp;
    }
}

// 指针版本
void ReversePtr(char *str) {
    char *end = str;
    char temp;
    while (*end != '\0') end++;
    end--; // 指向最后一个有效字符
    while (str < end) {
        temp = *str;
        *str = *end;
        *end = temp;
        str++;
        end--;
    }
}

int main() {
    char s[] = "Hello";
    ReversePtr(s);
    printf("%s\n", s);
    return 0;
}

