void Transpose(int (*a)[N], int n);

int main(void)
{
    int a[N][N], n, i, j;
    printf("Input n:");
    scanf("%d", &n);
    printf("Input %d*%d matrix:\n", n, n);
    for(i=0; i<n; i++)
        for(j=0; j<n; j++)
            scanf("%d", &a[i][j]);

    Transpose(a, n);

    printf("Transposed matrix:\n");
    for(i=0; i<n; i++){
        for(j=0; j<n; j++)
            printf("%4d", a[i][j]);
        printf("\n");
    }
    return 0;
}

void Transpose(int (*a)[N], int n)
{
    int i, j, temp;
    for(i=0; i<n; i++)
    {
        for(j=i+1; j<n; j++)
        {
            temp = a[i][j];
            a[i][j] = a[j][i];
            a[j][i] = temp;
        }
    }
}

