void Update(CLOCK *t) {
    t->second++;
    if (t->second == 60) {
        t->second = 0;
        t->minute++;
        if (t->minute == 60) {
            t->minute = 0;
            t->hour++;
            if (t->hour == 24) {
                t->hour = 0;
            }
        }
    }
}

int main() {
    CLOCK myClock = {23, 59, 59};
    printf("Current time: %02d:%02d:%02d\n", myClock.hour, myClock.minute, myClock.second);
    Update(&myClock);
    printf("New time: %02d:%02d:%02d\n", myClock.hour, myClock.minute, myClock.second);
    return 0;
}
