void Update(CLOCK *t) {
    t->second++;

    t->minute += t->second / 60;
    t->second = t->second % 60;

    t->hour += t->minute / 60;
    t->minute = t->minute % 60;

    t->hour = t->hour % 24;
}

int main() {
