编写一个程序，实现两个 `NodeType` 类型变量的加法运算。函数应根据 `type` 字段判断数据类型：
1. 若两个操作数均为 `int`，结果存储为 `int`。
2. 若其中一个或两个为 `double`，结果存储为 `double`。
输出计算结果。

questions.answer:
```c
#include <stdio.h>

typedef struct node
{
    int type; // 1: int, 2: double
    union
    {
        int ival;
        double dval;
    } dat;
} NodeType;

NodeType Add(NodeType a, NodeType b) {
    NodeType res;
    double valA, valB;

    valA = (a.type == 1) ? (double)a.dat.ival : a.dat.dval;
    valB = (b.type == 1) ? (double)b.dat.ival : b.dat.dval;

    if (a.type == 1 && b.type == 1) {
        res.type = 1;
        res.dat.ival = a.dat.ival + b.dat.ival;
    } else {
        res.type = 2;
        res.dat.dval = valA + valB;
    }
    return res;
}

int main() {
    NodeType n1, n2, res;

    // Test 1: int + int
    n1.type = 1; n1.dat.ival = 10;
    n2.type = 1; n2.dat.ival = 20;
    res = Add(n1, n2);
    printf("10 + 20 = %d\n", res.dat.ival);

    // Test 2: int + double
    n1.type = 1; n1.dat.ival = 5;
    n2.type = 2; n2.dat.dval = 3.5;
    res = Add(n1, n2);
    printf("5 + 3.5 = %.2f\n", res.dat.dval);

    return 0;
}
```

