    {
        printf("无法打开源文件 %s\n", srcName);
        exit(0);
    }

    // 以追加模式打开目标文件
    if ((fpDest = fopen(destName, "a")) == NULL)
    {
        printf("无法打开目标文件 %s\n", destName);
        fclose(fpSrc);
        exit(0);
    }

    while ((ch = fgetc(fpSrc)) != EOF)
    {
        fputc(ch, fpDest);
    }

    printf("文件追加完成\n");

    fclose(fpSrc);
    fclose(fpDest);
    return 0;
}
```

